    /* A functional which takes a single parameter of a parametric type
     * bound by Any cannot be overloaded.
     */
    private def checkBoundAny(param: Type, sparams: List[StaticParam]): Boolean =
      if (param.isInstanceOf[VarType]) {
        val tyName = param.asInstanceOf[VarType].getName.getText
        sparams.exists(sp =>
                       sp.getName.getText.equals(tyName) &&
                       toList(sp.getExtendsClause).exists(_.isInstanceOf[AnyType]))
      } else false

    /* A pair's validity depends on its two signatures as instantiated where it is checked,
     * on the other signatures there, on whether they are dotted methods and on the static
     * parameters in scope, so a valid answer is reused only where all of these are equal. */
    private var staticParamsInScope: List[StaticParam] = Nil
    private val validOverloadingMemo = new scala.collection.mutable.HashMap[
        (ArrowType, Option[Int], ArrowType, Option[Int], Set[(ArrowType, Option[Int])], Boolean, List[StaticParam]), Boolean]()

    private def validOverloading(first: (ArrowType,Option[Int],Option[JavaFunctional]),
				 second: (ArrowType,Option[Int],Option[JavaFunctional]),
      !isMethod && first._2.isDefined && first._2 == second._2 &&
      first._3.exists(isFunctionalMethod) && second._3.exists(isFunctionalMethod)

    private def meetRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
    	                 second: (ArrowType,Option[Int],Option[JavaFunctional]),
			 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			 isMethod: Boolean,
			 oa: OverloadingOracle,
			 debug : Boolean = false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      val b1 = fsp == gsp
      val b2 = (fsp == gsp) &&
      signatures.exists(third => third match {
           case (ha, hsp, _) => {
              val a1 = (hsp == fsp) 
              val a2 = a1 && oa.lteq(ha, fa) 
              val a3 = a2 && oa.lteq(ha, ga) 
              val a4 = a3 && (if (isMethod && fsp.isDefined)
                                oa.isMeet(withoutSelf(ha, fsp.get), withoutSelf(fa, fsp.get), withoutSelf(ga, fsp.get), false, debug)
                              else oa.isMeet(ha, fa, ga, isMethod, debug))
     //         if (debug)
     //             println("" + ha + " " + a1 + a2 + a3 + a4)

              a4}})
      b2
    }

    // the self parameter of a functional method is compared as a dotted method's receiver is, wherever it sits
    private def withoutSelf(a: ArrowType, i: Int): ArrowType = {
      val d = a.getDomain match {
        case t: TupleType =>
          NF.makeTupleType(NU.getSpan(t), toJavaList(toListFromImmutable(t.getElements).zipWithIndex.filter(_._2 != i).map(_._1)))
        case t => NF.makeTupleType(NU.getSpan(t), toJavaList(List[Type]()))
      }
      NF.makeArrowType(NU.getSpan(a), d, a.getRange, a.getInfo.getStaticParams)
    }

    /* The Meet Rule's closed-trait case, for functions and functional methods: the
     * declarations whose domains are below both domains together hold every value of
     * their overlap, as the comprises clauses show (OverloadingOracle.coversOverlap). */
    private def coverageRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                             second: (ArrowType,Option[Int],Option[JavaFunctional]),
                             signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                             isMethod: Boolean,
